/* The shape of hl7-data.js, generated by support/build-dictionary.mts */
import type { HL7MessageDefinition } from '../src/types.js';

/** [type, desc, opt, rep, len, table, item, minLen, confLen, truncate] - trailing nulls left out */
export type HL7DataField = [
  type: string,
  desc?: string | null,
  opt?: string | null,
  rep?: number | 'infinite' | null,
  len?: number | null,
  table?: number | null,
  item?: number | null,
  minLen?: number | null,
  confLen?: number | null,
  truncate?: boolean | null,
];

/** [desc, field indexes by position - null where the version withdrew the field] */
export type HL7DataSegment = [desc: string | null, fields: (number | null)[]];

/** [desc, field indexes, or null for a primitive type] */
export type HL7DataType = [
  desc: string | null,
  fields: (number | null)[] | null,
];

/** Name to index in segments, types and messages */
export type HL7DataVersion = [
  segments: Record<string, number>,
  types: Record<string, number>,
  messages: Record<string, number>,
];

export interface HL7Data {
  fields: HL7DataField[];
  segments: HL7DataSegment[];
  types: HL7DataType[];
  messages: HL7MessageDefinition[];
  versions: Record<string, HL7DataVersion>;
  /** Table number: [description, { code: text }] - one set for every version */
  tables: Record<string, [desc: string | null, values: Record<string, string>]>;
}

declare const data: HL7Data;
export default data;
